import type { Eyes as BaseEyes, Target, CheckSettings, CloseSettings, AbortSettings, GetResultsSettings, TestResult } from '@applitools/core-base';
import type { Snapshot } from '../ufg/types';
import type { Eyes, Environment } from '../automation/types';
import type { Eyes as ClassicEyes, CheckSettings as ClassicCheckSettings } from '../classic/types';
import type { Captured } from '../classic/utils/capture';
import type { Driver } from '@applitools/driver';
import type { UFGClient, RenderTarget, Environment as UFGEnvironment } from '@applitools/ufg-client';
import type { Logger } from '@applitools/logger';
import type { Task, TaskManager, TaskSpec, Deps } from '@applitools/task-manager';
import type { AbortSignal } from 'abort-controller';
import type { buildAccessibilityReportOptions } from '../ufg/build-accessibility-report-options';
/** A test's identity in the graph: its tasks carry it in their labels, and it keeps their opens queryable. */
export type Session = object;
/** Where a task belongs: its test and environment. */
export type Labels = {
    session: Session;
    env: string;
};
export type MatchTarget = {
    target: Target;
    settings: CheckSettings;
};
export type MatchResult = {
    asExpected: boolean;
};
export type EnvironmentResult = TestResult & {
    environment: BaseEyes['test']['environment'];
};
/** An environment's open. `eyes.type` picks the opener. */
export type OpenInputs = {
    eyes: Eyes<any>;
    environment: Environment;
    driver?: Driver<any>;
    logger: Logger;
};
/** A classic check's capture of every environment. */
export type CaptureInputs = {
    eyes: ClassicEyes<any>;
    driver: Driver<any>;
    settings: ClassicCheckSettings<any>;
    environments: Environment[];
    /** A `matchTimeout` check's first capture: it waits for the opens (`deps`), and this long more on a new test. */
    newTestDelay?: number;
    logger: Logger;
};
/** A classic step's target: captured already, or its `index` in the check's still-running capture. */
export type UploadInputs = (MatchTarget | {
    index: number;
}) & {
    signal?: AbortSignal;
    logger: Logger;
};
export type CreateRenderTargetInputs = {
    ufgClient: UFGClient;
    snapshot: Snapshot;
    logger: Logger;
};
export type RenderInputs = {
    ufgClient: UFGClient;
    snapshot: Snapshot;
    environment: UFGEnvironment;
    /** Set only when the check configures an accessibility standard; each render then mints its own report URL. */
    accessibility?: Parameters<typeof buildAccessibilityReportOptions>[0];
    signal?: AbortSignal;
    logger: Logger;
};
export type MatchInputs = {
    canFuse: boolean;
    /** Set when the check's target assumes mutability: the step logs that. */
    mutability?: {
        eyes: Eyes<any>;
        checkName?: string;
    };
    signal?: AbortSignal;
    onError?: (error: any, baseEyes: BaseEyes) => void;
    logger: Logger;
};
export type RecheckInputs = {
    /** The step's render, retargeted at the previous browser version. */
    render: RenderInputs;
    /** Sessions whose backend stopped expecting old-infra retries. */
    disabled: WeakSet<BaseEyes>;
    logger: Logger;
};
export type MatchAndEndInputs = {
    match: MatchInputs;
    settings?: CloseSettings;
};
export type CloseInputs = {
    settings?: CloseSettings;
    logger: Logger;
};
export type AbortInputs = {
    settings?: AbortSettings;
    logger: Logger;
};
export type GetResultsInputs = {
    settings?: GetResultsSettings;
    logger: Logger;
};
export type AbortedCheckInputs = {
    error: Error;
};
/** Each core task type's result and inputs. */
interface TaskContracts {
    open: {
        result: BaseEyes;
        inputs: OpenInputs;
    };
    capture: {
        result: Captured[];
        inputs: CaptureInputs;
    };
    upload: {
        result: MatchTarget | undefined;
        inputs: UploadInputs;
    };
    createRenderTarget: {
        result: RenderTarget;
        inputs: CreateRenderTargetInputs;
    };
    render: {
        result: MatchTarget;
        inputs: RenderInputs;
    };
    match: {
        result: MatchResult;
        inputs: MatchInputs;
    };
    matchAndEnd: {
        result: MatchResult;
        inputs: MatchAndEndInputs;
    };
    recheck: {
        result: void;
        inputs: RecheckInputs;
    };
    fill: {
        result: void;
        inputs: undefined;
    };
    close: {
        result: void;
        inputs: CloseInputs;
    };
    abort: {
        result: void;
        inputs: AbortInputs;
    };
    getResults: {
        result: EnvironmentResult;
        inputs: GetResultsInputs;
    };
    abortedCheck: {
        result: never;
        inputs: AbortedCheckInputs;
    };
}
export type TaskType = keyof TaskContracts;
export type Result<K extends TaskType> = TaskContracts[K]['result'];
export type Inputs<K extends TaskType> = TaskContracts[K]['inputs'];
/** A task of core's graph, by its result. */
export type GraphTask<TResult = unknown> = Task<TResult, unknown, Labels>;
/** Any core task, discriminated by `type`. */
type CoreTask = {
    [K in TaskType]: Task<Result<K>, Inputs<K>, Labels> & {
        readonly type: K;
    };
}[TaskType];
/** A collapse replacement for a `K` task: a task of a type whose result the fused originals settle with. */
type Replacement<K extends TaskType, TDeps extends Deps<Labels>> = {
    [R in TaskType]: Result<R> extends Result<K> ? Omit<TaskSpec<Result<R>, Inputs<R>, Labels, TDeps>, 'deps' | 'after'> & {
        type: R;
    } : never;
}[TaskType];
/**
 * Core's graph. `add` holds every task, and every collapse replacement, to its type's contract, so a query by type
 * can rely on it, and a `collapse` can tell its successor apart by type.
 */
export interface Graph {
    add<K extends TaskType, TDeps extends Deps<Labels> = Deps<Labels>>(spec: Omit<TaskSpec<Result<K>, Inputs<K>, Labels, TDeps>, 'collapse'> & {
        type: K;
        collapse?(successor: CoreTask): Replacement<K, TDeps> | undefined;
    }): Task<Result<K>, Inputs<K>, Labels>;
    filter: TaskManager<Labels>['filter'];
    dismiss: TaskManager<Labels>['dismiss'];
}
export {};
